    ]),
  );
  const entities: ObservedEntity[] = Array.from({ length: 50 }, (_, id) => ({
    type: "/api/items",
    collection: "/api/items",
    id: String(id),
    order: [0, id],
    observations: [1, 2].map((ordinal) => ({
      position: ordinal,
      index: id,
      ordinal,
      tool: "get_items",
      item: false,
      object: members,
    })),
  }));
  let retained = 0;
  lineShapes(entities, (bytes) => {
