    fallback_reason: null,
    xvfb_stderr_bytes: 0,
    status: "error",
    failure_code: "private_display_unavailable",
  } as const;
  expect(
    projectAnalysisError(new HopperProcessError(null, { diagnostic })).details
      ?.diagnostics,
  ).toEqual(diagnostic);
  const generic = { caller_context: "retained" };
  expect(
