import { expect, it } from "vitest";
import {
  AnalysisCancelledError,
  AnalysisInputError,
  AnalysisOutputError,
  AnalysisResourceConstraintError,
  AnalysisTimeoutError,
} from "./analysisErrorCore.js";
import { analysisErrorWithCleanupFailure } from "./analysisErrorCleanup.js";
import {
  projectAnalysisError,
  projectAnalysisErrorWithoutCapturedOutput,
} from "./analysisErrorProjection.js";
import {
  analysisErrorCategory,
  analysisErrorRemediationAction,
  analysisErrorUserMessage,
} from "./analysisErrorPresentation.js";
import { ProviderCleanupError } from "./providerCleanupError.js";
import { createEvidence } from "./evidence.js";
import { ArtifactOperationError } from "./artifactOperationError.js";

it.each([false, true])(
  "keeps each owner's capture without text-based deduplication (matching: %s)",
  (matching) => {
    const primary = new AnalysisTimeoutError("inspect", 1234, {
      capturedOutput: {
        stdout: "primary-capture-sentinel",
        stderr: "",
        truncated: false,
      },
    });
    const cleanup = new ProviderCleanupError(
      "fixture",
      ["owned-worker"],
      {},
      {
        capturedOutput: {
          stdout: matching
            ? "primary-capture-sentinel"
            : "cleanup-capture-sentinel",
          stderr: "",
          truncated: true,
        },
      },
    );
    const composed = analysisErrorWithCleanupFailure(
      primary,
      cleanup,
      "inspect",
    );
    const projected = projectAnalysisError(composed);
    expect(projected.details?.captured_output).toEqual(primary.capturedOutput);
    expect(projected.details?.diagnostics).toMatchObject({
      primary_error: {
        code: "provider_timeout",
        details: { timeout_ms: 1234 },
      },
      cleanup_error: { details: { captured_output: cleanup.capturedOutput } },
    });
    expect(
      JSON.stringify(projected).split("primary-capture-sentinel"),
    ).toHaveLength(matching ? 3 : 2);
    if (!matching)
      expect(
        JSON.stringify(projected).split("cleanup-capture-sentinel"),
      ).toHaveLength(2);
    expect(
      projectAnalysisErrorWithoutCapturedOutput(primary).details,
    ).not.toHaveProperty("captured_output");
    expect(projectAnalysisError(primary).details?.captured_output).toEqual(
      primary.capturedOutput,
    );
  },
);

it("keeps dependency-owned resources empty after the final owner releases", () => {
  const file = new ProviderCleanupError("fixture", ["file-owner"], {});
  const trace = new ProviderCleanupError("fixture", ["trace-owner"], {});
  const composed = analysisErrorWithCleanupFailure(
    file,
    trace,
  ).bindCleanupDependencies([file, trace]);
  expect(new Set(composed.cleanupResources)).toEqual(
    new Set(["file-owner", "trace-owner"]),
  );
  file.resolveCleanup();
  expect(composed.cleanupResources).toEqual(["trace-owner"]);
  trace.resolveCleanup();
  expect(composed.cleanupIncomplete).toBe(false);
  expect(composed.cleanupResources).toEqual([]);
  expect(new Set(composed.cleanup?.resources)).toEqual(
    new Set(["file-owner", "trace-owner"]),
  );
});

it("keeps primary diagnostics separate from historical cleanup diagnostics with the same keys", () => {
  const primary = new AnalysisInputError("inspect", {
    diagnostics: {
      primary_error: "source observation",
      cleanup_error: "another source observation",
    },
  });
  const cleanup = new ProviderCleanupError("fixture", ["owned-input"], {});
  const composed = analysisErrorWithCleanupFailure(
    primary,
    cleanup,
  ).bindCleanupDependencies([primary, cleanup]);
  cleanup.resolveCleanup();
  const projected = projectAnalysisError(composed);
  expect(projected.details?.diagnostics).toEqual(primary.diagnostics);
  expect(projected.details?.cleanup_history).toMatchObject({
    primary_error: projectAnalysisError(primary),
    cleanup_error: { code: "cleanup_incomplete" },
  });
  expect(composed.cleanupPrimary).toBe(primary);
  expect(Object.hasOwn(composed, "cleanupPrimary")).toBe(false);
});

it.each([
  new ArtifactOperationError(
    "inspect_asset_catalog",
    "integrity",
    undefined,
    "Asset catalog changed during inspection: Contents/Resources/Assets.car",
  ),
  new AnalysisInputError("inspect", { diagnostics: { input: "original" } }, [
    {
      path: ["path"],
      reason: "out_of_range",
      message: "fixed input allowance",
    },
  ]),
  new AnalysisCancelledError("inspect", { cause: "caller reason" }),
  new AnalysisTimeoutError("inspect", 1234),
  new AnalysisResourceConstraintError(
    "inspect",
    "file-size",
    "fixed input allowance",
    { maximum_input_bytes: 123 },
    { retryable: false, remediationAction: "Select a smaller suitable input." },
  ),
  new AnalysisOutputError("inspect", "invalid output", {
    capturedOutput: {
      stdout: "original output",
      stderr: "original warning",
      truncated: true,
    },
    partialObservation: createEvidence(
      undefined,
      { id: "fixture", name: "Fixture", version: null },
      {
        operation: "inspect",
        parameters: {},
        result: { original_fact: true },
        confidence: "observed",
        locations: [],
        limitations: [],
      },
    ),
  }),
])("restores the typed $_tag primary after confirmed cleanup", (primary) => {
  const original = projectAnalysisError(primary);
  const cleanup = new ProviderCleanupError(
    "fixture",
    ["owned-input"],
    { reason: "close denied" },
    {
      operation: "inspect",
      cleanup: { reason: "close denied", resources: ["owned-input"] },
    },
  );
  const composed = analysisErrorWithCleanupFailure(
    primary,
    cleanup,
    "inspect",
  ).bindCleanupDependencies([primary, cleanup]);
  expect(composed.cleanup?.reason).toBe("close denied");
  expect(composed.cleanup?.reason).not.toBe(
    projectAnalysisError(cleanup).message,
  );
  const pending = projectAnalysisError(composed);
  expect(pending.code).toBe("cleanup_incomplete");
  expect(pending.category).toBe(original.category);
  expect(analysisErrorCategory(composed)).toBe(original.category);
  const { diagnostics: _diagnostics, ...semanticDetails } =
    original.details ?? {};
  expect(pending.details).toMatchObject({
    ...semanticDetails,
    cleanup: "incomplete",
    execution_failure: original.code,
    resources: ["owned-input"],
  });
  cleanup.resolveCleanup();
  const projected = projectAnalysisError(composed);
  expect(projected).toMatchObject(original);
  expect(projected.details?.cleanup_history).toMatchObject({
    primary_error:
      primary.capturedOutput === undefined
        ? original
        : projectAnalysisErrorWithoutCapturedOutput(primary),
    cleanup_error: { code: "cleanup_incomplete" },
  });
  expect(projected.details).not.toHaveProperty("cleanup", "incomplete");
  expect(projected.details).not.toHaveProperty("resources");
  expect(analysisErrorCategory(composed)).toBe(original.category);
  expect(analysisErrorUserMessage(composed)).toBe(original.message);
  expect(analysisErrorRemediationAction(composed)).toBe(
    original.remediation.action,
  );
  expect(composed.cause).toBeInstanceOf(AggregateError);
  expect((composed.cause as AggregateError).errors[0]).toBe(primary);
});

it.each(["inner", "outer"] as const)(
  "waits for both nested cleanup owners when %s resolves first",
  (first) => {
    const primary = new AnalysisInputError("inspect", undefined, [
      { path: ["path"], reason: "missing_argument" },
    ]);
    const innerCleanup = new ProviderCleanupError("fixture", ["input"], {});
    const outerCleanup = new ProviderCleanupError("fixture", ["workspace"], {});
    const inner = analysisErrorWithCleanupFailure(
      primary,
      innerCleanup,
    ).bindCleanupDependencies([primary, innerCleanup]);
    const outer = analysisErrorWithCleanupFailure(
      inner,
      outerCleanup,
    ).bindCleanupDependencies([inner, outerCleanup]);
    const released = first === "inner" ? innerCleanup : outerCleanup;
    const pending = first === "inner" ? outerCleanup : innerCleanup;
    expect(projectAnalysisError(outer)).toMatchObject({
      code: "cleanup_incomplete",
      category: "invalid_input",
      details: {
        operation: "inspect",
        issues: primary.issues,
        execution_failure: "invalid_request",
      },
    });
    released.resolveCleanup();
    expect(outer.cleanupIncomplete).toBe(true);
    expect(projectAnalysisError(outer).code).toBe("cleanup_incomplete");
    expect(projectAnalysisError(outer).category).toBe("invalid_input");
    pending.resolveCleanup();
    expect(outer.cleanupIncomplete).toBe(false);
    expect(projectAnalysisError(outer)).toMatchObject(
      projectAnalysisError(primary),
    );
  },
);

it("does not infer cleanup success when a composition has no live owner binding", () => {
  const primary = new AnalysisInputError("inspect");
  const cleanup = new ProviderCleanupError("fixture", ["input"], {});
  const composed = analysisErrorWithCleanupFailure(primary, cleanup);
  cleanup.resolveCleanup();
  expect(projectAnalysisError(composed).code).toBe("cleanup_incomplete");
  expect(projectAnalysisError(composed).category).toBe("invalid_input");
  expect(composed.cleanupIncomplete).toBe(true);
});

it("keeps the physical failure primary when later cleanup observes cancellation", () => {
  const physical = Object.assign(new Error("selected file read EIO"), {
    code: "EIO",
  });
  const primary = new ArtifactOperationError(
    "inspect_asset_catalog",
    "io",
    undefined,
    physical.message,
    { cause: physical },
  );
  const reason = { request: "cancel after read failure" };
  const cleanup = new ProviderCleanupError(
    "fixture",
    ["owned-input"],
    {},
    {
      cause: new AnalysisCancelledError("inspect", { cause: reason }),
    },
  );
  const composed = analysisErrorWithCleanupFailure(
    primary,
    cleanup,
    "inspect",
  ).bindCleanupDependencies([primary, cleanup]);
  expect(projectAnalysisError(composed)).toMatchObject({
    code: "cleanup_incomplete",
    category: "execution_failure",
    details: {
      operation: "inspect_asset_catalog",
      reason: "io",
      detail: physical.message,
      execution_failure: "artifact_operation_failed",
    },
  });
  expect(composed.cleanupPrimary?.cause).toBe(physical);
  cleanup.resolveCleanup();
  expect(projectAnalysisError(composed)).toMatchObject(
    projectAnalysisError(primary),
  );
});

it("retains an observation attached to the composite after the primary failed", () => {
  const primary = new AnalysisInputError("inspect");
  const cleanup = new ProviderCleanupError("fixture", ["input"], {});
  const composed = analysisErrorWithCleanupFailure(
    primary,
    cleanup,
  ).bindCleanupDependencies([primary, cleanup]);
  const observation = createEvidence(
    undefined,
    { id: "fixture", name: "Fixture", version: null },
    {
      operation: "inspect",
      parameters: {},
      result: { late_fact: true },
      confidence: "observed",
      locations: [],
      limitations: [],
    },
  );
  composed.retainPartialObservation(observation);
  composed.resolveCleanup();
  expect(projectAnalysisError(composed).code).toBe("cleanup_incomplete");
  cleanup.resolveCleanup();
  expect(projectAnalysisError(composed)).toMatchObject({
    code: "invalid_request",
    details: { partial_observation: observation },
  });
});

it("retains an owner's finalization report independently of pending primary semantics", () => {
  const report = {
    owned_process_group: { state: "not_required" as const, reason: null },
    terminal_renderer: { state: "not_required" as const, reason: null },
    temporary_root: { state: "cleaned" as const, reason: null },
  };
  class ReportedCleanup extends ProviderCleanupError {
    override readonly cleanupReport = report;
  }
  const primary = new AnalysisInputError("inspect", undefined, [
    { path: ["path"], reason: "missing_argument" },
  ]);
  const finalized = new ReportedCleanup(
    "fixture",
    ["input"],
    {},
    {
      cleanupPrimary: primary,
    },
  );
  const later = new ProviderCleanupError("fixture", ["workspace"], {});
  const outer = analysisErrorWithCleanupFailure(
    finalized,
    later,
  ).bindCleanupDependencies([finalized, later]);
  const assertReport = (error: typeof outer) => {
    expect(projectAnalysisError(error)).toMatchObject({
      category: "invalid_input",
      details: {
        operation: "inspect",
        issues: primary.issues,
        cleanup_report: report,
      },
    });
  };
  assertReport(finalized);
  assertReport(outer);
  expect(outer.cleanupIncomplete).toBe(true);
  later.resolveCleanup();
  assertReport(outer);
  expect(outer.cleanupIncomplete).toBe(true);
  finalized.resolveCleanup();
  assertReport(outer);
  expect(outer.cleanupIncomplete).toBe(false);
});

src/domain/explicitSensitiveFailure.test.source:
import { EvidenceFileError } from "./evidenceErrors.js";
import {
  AnalysisAccessDeniedError,
  AnalysisInputError,
  AnalysisCapabilityUnavailableError,
  AnalysisCancelledError,
  AnalysisTimeoutError,
  AnalysisArtifactChangedError,
  AnalysisOutputError,
  AnalysisResourceConstraintError,
} from "./analysisErrorCore.js";
import { expect, it } from "vitest";
import { projectAnalysisError } from "./analysisErrorProjection.js";
import { ProviderCleanupError } from "./providerCleanupError.js";
import { ProviderAdapterError } from "./providerAdapterError.js";
import { analysisErrorWithCleanupFailure } from "./analysisErrorCleanup.js";
import { resolvedAnalysisError } from "./analysisErrorBase.js";
import { createEvidence } from "./evidence.js";
import {
  redactExplicitFailure,
  redactExplicitPointer,
} from "./explicitSensitiveFailure.js";

const context = {
  diagnostics: {
    note: "explicit-secret warning",
    nested: { "explicit-secret-key": 5, observed: 7 },
    caller_path: "/tmp/password-fixture?token=public-value",
  },
  capturedOutput: {
    stdout: "explicit-secret output",
    stderr: "public stderr",
    stdout_bytes: 22,
    truncated: false,
  },
};

it.each([
  new AnalysisCancelledError("inspect", context),
  new AnalysisTimeoutError("inspect", 250, context),
  new AnalysisInputError("inspect", context),
  new AnalysisAccessDeniedError("inspect", "/public", "EACCES", context),
  new AnalysisArtifactChangedError("inspect", "/public", "changed", context),
  new AnalysisOutputError("inspect", "invalid", context),
  new AnalysisCapabilityUnavailableError(
    "provider",
    "inspect",
    "unsupported",
    context,
  ),
  new AnalysisResourceConstraintError(
    "inspect",
    "memory",
    "capacity",
    null,
    context,
  ),
  new ProviderAdapterError("provider", "inspect", context),
])("preserves sanitized common context for $._tag", (error) => {
  const observation = createEvidence(
    undefined,
    { id: "fixture", name: "Owner facts", version: "1" },
    {
      operation: "inspect",
      parameters: {},
      result: { source: "already sanitized owner facts" },
      confidence: "observed",
      authority: "historical-reference",
    },
  );
  error.retainPartialObservation(observation);
  const sanitized = redactExplicitFailure(error, ["explicit-secret"]);
  expect(sanitized.partialObservation).toBe(observation);
  expect(sanitized._tag).toBe(error._tag);
  const projected = projectAnalysisError(sanitized);
  expect(projected.details).toMatchObject({
    diagnostics: {
      note: "[REDACTED] warning",
      nested: { observed: 7 },
      caller_path: context.diagnostics.caller_path,
    },
    captured_output: {
      stdout: "[REDACTED] output",
      stdout_bytes: 22,
      stderr: "public stderr",
    },
  });
  expect(JSON.stringify(projected)).not.toContain("explicit-secret");
});

it.each([
  ["/metadata/private~1~0/numeric", ["private/~"], "/metadata"],
  ["/metadata/private/child", ["private"], "/metadata"],
  ["/ordinary/path", [], "/ordinary/path"],
])(
  "preserves a real parent for excluded pointer identities: %s",
  (pointer, values, expected) => {
    expect(redactExplicitPointer(pointer, values)).toBe(expected);
  },
);

it("preserves cleanup failure authority and resources while excluding diagnostics", () => {
  const error = new ProviderCleanupError(
    "har",
    ["/root/private/capture", "pid:123"],
    {
      capture_path: "/root/private/capture",
      nested: { "private-key": 5, ordinary: "private ordinary" },
      exit_code: 2,
    },
    { operation: "inspect_web_network_capture" },
  );
  const projected = projectAnalysisError(
    redactExplicitFailure(error, ["private", "REDACTED"]),
  );
  expect(projected).toMatchObject({
    code: "cleanup_incomplete",
    details: {
      resources: expect.arrayContaining(["pid:123"]),
      diagnostics: { exit_code: 2 },
    },
  });
  expect(JSON.stringify(projected)).not.toContain("private");
  expect(JSON.stringify(projected)).not.toContain("REDACTED");
});

it("redacts cleanup primaries and mirrors the source error's live status", () => {
  const primary = new AnalysisInputError(
    "inspect_web_network_capture",
    undefined,
    [
      {
        path: ["capture_path", "/root/private-marker/capture.har"],
        reason: "invalid_value",
        message: "Selected private-marker capture was invalid",
      },
    ],
  );
  const cleanup = new ProviderCleanupError(
    "har",
    ["/tmp/private-marker-runtime"],
    { reason: "private-marker runtime close failed" },
    { operation: "inspect_web_network_capture" },
  );
  const original = analysisErrorWithCleanupFailure(
    primary,
    cleanup,
    "inspect_web_network_capture",
  );

  const redacted = redactExplicitFailure(original, ["private-marker"]);
  expect(redacted.cleanupIncomplete).toBe(true);
  expect(redacted.cleanupResources).toEqual(["/tmp/[REDACTED]-runtime"]);
  expect(JSON.stringify(projectAnalysisError(redacted))).not.toContain(
    "private-marker",
  );

  original.resolveCleanup();
  expect(redacted.cleanupIncomplete).toBe(false);
  const resolved = resolvedAnalysisError(redacted);
  expect(JSON.stringify(projectAnalysisError(resolved))).not.toContain(
    "private-marker",
  );
  expect(projectAnalysisError(resolved).details).toMatchObject({
    issues: [
      {
        path: ["capture_path", "/root"],
        reason: "invalid_value",
      },
    ],
  });
});

it("keeps a named timeout control through explicit-value redaction", () => {
  const error = new AnalysisTimeoutError(
    "analyze_javascript_application",
    300000,
    {
      userMessage:
        "JavaScript source analysis reached its 300000ms per-source server/provider deadline (analysis_timeout_ms) for explicit-secret, not the MCP client deadline.",
      remediationAction:
        "Increase analysis_timeout_ms through MCP for explicit-secret, or use rea analyze-javascript-application <input_path> --analysis-timeout-ms <milliseconds> on the CLI.",
    },
  );
  const redacted = redactExplicitFailure(error, ["explicit-secret"]);
  const projected = projectAnalysisError(redacted);
  expect(projected.message).toContain("analysis_timeout_ms");
  expect(projected.message).toContain("300000");
  expect(projected.remediation.action).toContain("analysis_timeout_ms");
  expect(projected.remediation.action).toContain("--analysis-timeout-ms");
  expect(JSON.stringify(projected)).not.toContain("explicit-secret");
});

it("keeps unsupported profile reasons distinct from malformed input", () => {
  const error = new AnalysisCapabilityUnavailableError(
    "mitmproxy",
    "inspect_web_network_capture",
    "Unsupported private profile",
    { userMessage: "Select private-compatible profile" },
  );
  const result = redactExplicitFailure(error, ["private"]);
  expect(result).toBeInstanceOf(AnalysisCapabilityUnavailableError);
  expect(projectAnalysisError(result).code).toBe("capability_unavailable");
  expect(JSON.stringify(projectAnalysisError(result))).not.toContain("private");
});

it("preserves a retryable capability failure through explicit-value redaction", () => {
  // Retryability is a semantic field of the error, not presentation: dropping
  // it turns a transient admission failure into a permanent one and changes
  // the remediation the caller is shown.
  const error = new AnalysisCapabilityUnavailableError(
    "mitmproxy",
    "inspect_web_network_capture",
    "Runtime admission for /targets/private/capture failed transiently",
    { retryable: true },
  );
  expect(projectAnalysisError(error).retryable).toBe(true);
  const result = redactExplicitFailure(error, ["private"]);
  expect(result).toBeInstanceOf(AnalysisCapabilityUnavailableError);
  expect((result as AnalysisCapabilityUnavailableError).retryable).toBe(true);
  expect(projectAnalysisError(result).retryable).toBe(true);
  expect(JSON.stringify(projectAnalysisError(result))).not.toContain("private");
});

it("coarsens format issue pointers without creating replacement coordinates", () => {
  const error = new AnalysisInputError(
    "inspect_web_network_capture",
    undefined,
    [
      {
        path: ["capture_path", "/metadata/private~1~0/nested"],
        reason: "invalid_format",
        message: "Malformed private field",
      },
    ],
  );
  const result = redactExplicitFailure(error, ["private/~", "private"]);
  if (!(result instanceof AnalysisInputError))
    throw new Error("Input error required");
  expect(result.issues[0]?.path).toEqual(["capture_path", "/metadata"]);
});

it("excludes a marked permission-denied path without losing its host error code", () => {
  const error = redactExplicitFailure(
    new AnalysisAccessDeniedError(
      "inspect_web_network_capture",
      "/declared-path-value/capture.har",
      "EACCES",
    ),
    ["declared-path-value"],
  );
  expect(error._tag).toBe("AnalysisAccessDeniedError");
  const projected = projectAnalysisError(error);
  expect(projected).toMatchObject({
    code: "access_denied",
    category: "unavailable",
    details: { system_code: "EACCES" },
  });
  expect(JSON.stringify(projected)).not.toContain("declared-path-value");
});

it("coarsens ordinary sensitive issue-path segments to their real parent", () => {
  const input = new AnalysisInputError(
    "inspect_web_network_capture",
    undefined,
    [
      {
        path: ["input", "mysecret", "child"],
        reason: "unknown_argument",
        message: "Unrecognized mysecret",
      },
    ],
  );
  const result = redactExplicitFailure(input, ["secret"]);
  if (!(result instanceof AnalysisInputError))
    throw new Error("Input error required");
  expect(result.issues[0]?.path).toEqual(["input"]);
  expect(JSON.stringify(projectAnalysisError(result))).not.toContain("secret");
});

it("does not reinterpret an unknown argument name as a JSON pointer", () => {
  const input = new AnalysisInputError(
    "inspect_web_network_capture",
    undefined,
    [{ path: ["/ordinary/secret"], reason: "unknown_argument" }],
  );
  const result = redactExplicitFailure(input, ["secret"]);
  if (!(result instanceof AnalysisInputError))
    throw new Error("Input error required");
  expect(result.issues[0]?.path).toEqual([]);
});

it("preserves completed publication and live cleanup while excluding marked file identities", () => {
  const original = new EvidenceFileError("write", "io", {
    path: "/private-marker/output.json",
    published: { path: "/private-marker/output.json", bytes: 42 },
    cleanup: {
      reason: "private-marker staging failed",
      resources: ["/private-marker/stage"],
    },
  });
  const redacted = redactExplicitFailure(original, ["private-marker"]);
  const projected = projectAnalysisError(redacted);
  expect(projected).toMatchObject({
    code: "cleanup_incomplete",
    details: { published: true, bytes: 42 },
  });
  expect(projected.details).not.toHaveProperty("path");
  expect(projected.details).not.toHaveProperty("published_path");
  expect(JSON.stringify(projected)).not.toContain("private-marker");
  original.resolveCleanup();
  expect(redacted.cleanupIncomplete).toBe(false);
});

